  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Temperature parameter tau for softmax scaling, default 1.0\n    tau = float(extra.get('weight_tau', 1.0))\n    raw = (gap / tau).exp()\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=4.0, neginf=0.0).clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=raw, meta={'builder': 'all_pairs', 'weight_family': 'gap_softmax'})\n"
}

{
  "name": "reweight_gap_sigmoid",
  "intuition": "Combine the gap_linear base with a sigmoid transformation to smoothly interpolate weights, adding robustness and handling outliers better. This crossover retains the pair construction and introduces a flexible, bounded weighting function that improves stability across diverse objectives.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["all_pairs", "sigmoid", "clamp", "sub", "mul"],
  "implementation_hint": {
    "expects": ["objective", "log_prob", "obj_z", "rank", "regret"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    log_prob = feature_cache['log_prob']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    pair_count = int(b_idx.numel())\n    if pair_count <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'reweight_gap_sigmoid', 'weight_family': 'gap_sigmoid'})\n    # Apply sigmoid transform for smooth weighting\n    raw = gap.clamp_min(0.0)\n    normalized = raw / (raw.max() if hasattr(raw, 'max') else 1.0 + 1e-6)\n    weight = torch.sigmoid(normalized * 10.0)  # scale for sharper transition\n    weight = weight.clamp(0.0, 1.0)  # ensure bounds\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'reweight_gap_sigmoid', 'weight_family': 'gap_sigmoid'})"
}

