{
  "name": "all_pairs_gap_sigmoid_simple",
  "intuition": "Reweight all pairs using a simple sigmoid gap transformation without imports, emphasizing moderate gaps with clamping",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_sigmoid",
    "constraint_family": "clamp_only"
  },
  "operators_used": [
    "all_pairs",
    "sigmoid",
    "clamp"
  ],
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Compute mask for all pairs where objective_i < objective_j\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        from torch import int64\n        empty_idx = b_idx.to(int64)\n        return PrefBatch(mode='pairwise', pair_idx=(empty_idx, empty_idx, empty_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    beta = float(extra.get('weight_beta', 5.0))\n    shift = float(extra.get('weight_shift', 0.5))\n    raw = (1 / (1 + (-beta * (gap - shift)).exp()))\n    clamp_lo = 0.1\n    clamp_hi = 4.0\n    weight = raw.clamp(min=clamp_lo, max=clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_sigmoid'})"
}
