{
  "name": "reweight_all_pairs_gap_combined",
  "intuition": "Combines the pairwise gap linear idea with a monotone transform inspired by softplus to achieve smooth, non-negative weights that emphasize larger gaps while maintaining stability and robustness. Incorporates the fixed pairwise topology and preserves the pair construction logic, enhancing the weight signal with a smooth, monotonic mapping for better gradient behavior.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
    "weight_family": "gap_combined_poly",
    "constraint_family": "clamp_only"
  },
  "operators_used": ["gap_linear", "ops_softplus", "ops_clamp", "ops_mul", "ops_add", "ops_sub", "ops_tril", "ops_zeros_like"],
  "implementation_hint": {
    "expects": ["objective", "log_prob"],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    # Use the fixed pairwise mask\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    # Compute gap\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Apply linear gap transformation\n    raw_weight = gap.clamp_min(0.0)\n    # Transform seamlessly with smooth monotonic function\n    weight = ops.softplus(raw_weight)  # ensures positivity and smoothness\n    # Optional: clamp for stability\n    weight = ops.clamp(weight, 0.0, extra.get('max_weight', 10.0))\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'reweight_all_pairs_gap_combined', 'weight_family': 'gap_combined_poly'})"
}

