  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    clamp_lo = float(extra.get('clamp_lo', 0.15))\n    clamp_hi = float(extra.get('clamp_hi', 3.5))\n    window_width = float(extra.get('window_width', 1.0))\n    # Apply soft linear clamping with a smooth window function\n    # Compute a smooth mask between clamp_lo-window_width and clamp_hi+window_width\n    lower_edge = clamp_lo\n    upper_edge = clamp_hi\n    gap_pos = gap.clamp_min(0.0)  # relu equivalent\n    # Compute smooth lower ramp\n    smooth_lower = (gap_pos - (lower_edge - window_width)) / window_width\n    smooth_lower = smooth_lower.clamp(0.0, 1.0)\n    # Compute smooth upper ramp\n    smooth_upper = ((upper_edge + window_width) - gap_pos) / window_width\n    smooth_upper = smooth_upper.clamp(0.0, 1.0)\n    smooth_mask = smooth_lower * smooth_upper\n    raw = gap_pos * smooth_mask\n    weight = raw.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
}

