{
  "name": "builder_all_pairs_gap_bandpass_linear",
  "intuition": "Reweight all pairs on the fixed all-pairs mask by applying a linear bandpass filter on the positive gap, emphasizing mid-range gap values while suppressing very small or very large gaps.",
  "hyperparams": {
