  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'builder_all_pairs_gap_bandpass_linear', 'weight_family': 'gap_bandpass_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_pos = gap.clamp_min(0.0)\n    # Bandpass parameters with defaults\n    low = float(extra.get('bandpass_low', 0.3))  # lower cutoff\n    high = float(extra.get('bandpass_high', 2.0))  # upper cutoff\n    # Linear ramp up from low to center, ramp down from center to high\n    center = (low + high) * 0.5\n    weight = gap_pos.new_zeros(gap_pos.shape)\n    # Ramp up: (gap - low)/(center - low) for gap in [low, center]\n    ramp_up_mask = (gap_pos >= low) & (gap_pos <= center)\n    weight = weight + ramp_up_mask.to(gap_pos.dtype) * ((gap_pos - low) / max(center - low, 1e-6))\n    # Ramp down: (high - gap)/(high - center) for gap in [center, high]\n    ramp_down_mask = (gap_pos > center) & (gap_pos <= high)\n    weight = weight + ramp_down_mask.to(gap_pos.dtype) * ((high - gap_pos) / max(high - center, 1e-6))\n    clamp_lo = float(extra.get('clamp_lo', 0.1))\n    clamp_hi = float(extra.get('clamp_hi', 3.0))\n    weight = weight.clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'builder_all_pairs_gap_bandpass_linear', 'weight_family': 'gap_bandpass_linear'})"
