  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() <= 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_sigmoid_bandpass_001', 'weight_family': 'gap_sigmoid_bandpass'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # Parameters controlling the bandpass window\n    tau = float(extra.get('weight_tau', 1.0))\n    center = float(extra.get('weight_center', 1.5))\n    width = float(extra.get('weight_width', 1.0))\n    # Normalize gap by tau\n    g = gap / tau\n    # Sigmoid bandpass: sigmoid(-(g - center + width/2)) * sigmoid(g - center - width/2)\n    left = (g - (center - width / 2))\n    right = ((center + width / 2) - g)\n    raw = torch.sigmoid(left) * torch.sigmoid(right)\n    clamp_lo = 0.1\n    clamp_hi = 3.0\n    raw = torch.nan_to_num(raw, nan=0.0, posinf=3.0, neginf=0.0).clamp(clamp_lo, clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=raw, meta={'builder': 'all_pairs_gap_sigmoid_bandpass_001', 'weight_family': 'gap_sigmoid_bandpass'})"
