{
  "name": "builder_all_pairs_gap_bandpass_v1",
  "intuition": "Reweight pairs by emphasizing intermediate gap ranges via a bandpass triangular filter on positive gaps, suppressing pairs with too small or too large gaps to focus learning on moderately difficult distinctions.",
  "hyperparams": {
    "geometry_family": "dense_all_pairs",
    "cap_family": "uncapped_full",
