  },
  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass_triangular'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_pos = gap.clamp_min(0.0)\n    # Bandpass parameters (configurable via extra)\n    low = float(extra.get('weight_low', 0.5))\n    mid = float(extra.get('weight_mid', 1.5))\n    high = float(extra.get('weight_high', 3.0))\n    # Calculate triangular bandpass weight\n    weight = torch.zeros_like(gap_pos)\n    # Rising slope from low to mid\n    rising = (gap_pos - low) / (mid - low + 1e-6)\n    rising = rising.clamp(0.0, 1.0)\n    # Falling slope from mid to high\n    falling = (high - gap_pos) / (high - mid + 1e-6)\n    falling = falling.clamp(0.0, 1.0)\n    weight = rising * falling\n    # Ensure weight nonnegative and clamp for numerical safety\n    weight = weight.clamp(0.0, 4.0)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_bandpass_triangular'})"
}

