  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    pair_count = b_idx.numel()\n    if pair_count == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_clamped_v2'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_pos = gap.clamp_min(0.0)\n    tau = float(extra.get('weight_tau', 1.0))\n    scaled_gap = gap_pos / tau\n\n    import torch\n    # smooth lower clamp near 0.25 using softplus shifted\n    lower_bound = 0.25\n    lower_softplus_shift = 1.0\n    smooth_lower = torch.nn.functional.softplus(scaled_gap - lower_bound + lower_softplus_shift) - torch.nn.functional.softplus(lower_softplus_shift) + lower_bound\n\n    # smooth upper clamp near 4.0 using scaled tanh\n    upper_bound = 4.0\n    # scale approx tanh to upper_bound (1 + tanh ranges -1 to 1)\n    smooth_weight = lower_bound + (upper_bound - lower_bound) * 0.5 * (1 + torch.tanh((smooth_lower - (upper_bound + lower_bound)*0.5)*2))\n    smooth_weight = smooth_weight.clamp(min=lower_bound, max=upper_bound)\n\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=smooth_weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear_clamped_v2'})"
