  "code": "def generated_builder(feature_cache, extra):\n    import torch\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    # enforce minimum gap 0.25 with smoothplus shift\n    gap_shifted = torch.nn.functional.softplus(gap - 0.25) + 0.25\n    # impose a smooth upper cap near 4 using softplus inverted transform\n    upper_bound = 4.0\n    # Convert upper bound to softplus input space\n    inv_softplus = lambda x: torch.log(torch.exp(x) - 1.0)\n    max_softplus_input = inv_softplus(torch.tensor(upper_bound - 0.25))\n    # clamp input before softplus to softly cap\n    capped_input = torch.minimum(gap_shifted - 0.25, max_softplus_input)\n    weight = torch.nn.functional.softplus(capped_input) + 0.25\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs', 'weight_family': 'gap_linear'})"
}

