  "code": "def generated_builder(feature_cache, extra):\n    objective = feature_cache['objective']\n    mask = objective[:, :, None] < objective[:, None, :]\n    b_idx, winner_idx, loser_idx = mask.nonzero(as_tuple=True)\n    if b_idx.numel() == 0:\n        return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta={'builder': 'all_pairs_gap_bandpass_clip_v1', 'weight_family': 'gap_bandpass_clipped'})\n    gap = objective[b_idx, loser_idx] - objective[b_idx, winner_idx]\n    gap_pos = gap.clamp_min(0.0)\n    tau = float(extra.get('weight_tau', 1.0))\n    low_cut = float(extra.get('gap_bandpass_low', 0.5))\n    high_cut = float(extra.get('gap_bandpass_high', 3.0))\n    # Bandpass weighting: linearly ramp up from low_cut to 1.0, then ramp down to zero at high_cut\n    weight_high = (high_cut - gap_pos).clamp_min(0.0)\n    weight_low = (gap_pos - low_cut).clamp_min(0.0)\n    raw_weight = (weight_high * weight_low) / ( (high_cut - low_cut) ** 2 )\n    scaled_weight = raw_weight * tau\n    clamp_lo = 0.25\n    clamp_hi = 4.0\n    weight = scaled_weight.clamp(min=clamp_lo, max=clamp_hi)\n    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=weight, meta={'builder': 'all_pairs_gap_bandpass_clip_v1', 'weight_family': 'gap_bandpass_clipped'})"
